mapper.insert:

    SELECT
        'INSC'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(INTERVIEW_SCORE_NO), LENGTH('INSC' ) + 1)), 0) + 1, 6, '0')
    FROM INTERVIEW_SCORE

	INSERT INTO INTERVIEW_SCORE (
		INTERVIEW_SCORE_NO
		, INTERVIEW_QUESTION_NO
		, INTERVIEW_NO
		, APPLICANT_ID
		, APPLICANT_RATING
	) VALUES (
		#{interviewScoreNo}
		, #{interviewQuestionNo}
		, #{interviewNo}
		, #{applicantId}
		, #{applicantRating}
	)

mapper.update:
UPDATE INTERVIEW_SCORE SET 
	INTERVIEW_QUESTION_NO = #{interviewQuestionNo}
	, INTERVIEW_NO = #{interviewNo}
	, APPLICANT_ID = #{applicantId}
	, APPLICANT_RATING = #{applicantRating}
WHERE INTERVIEW_SCORE_NO = #{interviewScoreNo}
